import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.KEpKIwgx.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"docs/faq.md","filePath":"docs/faq.md","lastUpdated":null}'),o={name:"docs/faq.md"};function r(d,a,l,h,n,p){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="base-url-是什么" tabindex="-1">Base URL 是什么？ <a class="header-anchor" href="#base-url-是什么" aria-label="Permalink to &quot;Base URL 是什么？&quot;">​</a></h2><p>Base URL 是接口服务的基础地址。示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://bluebirdapi.com/v1</span></span></code></pre></div><h2 id="api-key-在哪里获取" tabindex="-1">API Key 在哪里获取？ <a class="header-anchor" href="#api-key-在哪里获取" aria-label="Permalink to &quot;API Key 在哪里获取？&quot;">​</a></h2><p>登录控制台后，在令牌或 API Key 管理页面创建并复制 API Key。</p><h2 id="为什么返回-401" tabindex="-1">为什么返回 401？ <a class="header-anchor" href="#为什么返回-401" aria-label="Permalink to &quot;为什么返回 401？&quot;">​</a></h2><p>通常是 API Key 缺失、错误、已删除或请求头格式不正确。请检查：</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer sk-xxxxxxxxxxxxxxxx</span></span></code></pre></div><h2 id="为什么返回-429" tabindex="-1">为什么返回 429？ <a class="header-anchor" href="#为什么返回-429" aria-label="Permalink to &quot;为什么返回 429？&quot;">​</a></h2><p>说明请求频率或并发过高。请降低并发，并使用指数退避重试。</p><h2 id="为什么模型不可用" tabindex="-1">为什么模型不可用？ <a class="header-anchor" href="#为什么模型不可用" aria-label="Permalink to &quot;为什么模型不可用？&quot;">​</a></h2><p>可能原因包括模型名称写错、账号无权限、模型暂时不可用或额度不足。请先调用 <code>/v1/models</code> 查看可用模型。</p><h2 id="为什么响应慢" tabindex="-1">为什么响应慢？ <a class="header-anchor" href="#为什么响应慢" aria-label="Permalink to &quot;为什么响应慢？&quot;">​</a></h2><p>可能与模型负载、输出长度、上下文长度、网络延迟有关。长文本建议启用 <code>stream=true</code>。</p><h2 id="流式响应为什么中断" tabindex="-1">流式响应为什么中断？ <a class="header-anchor" href="#流式响应为什么中断" aria-label="Permalink to &quot;流式响应为什么中断？&quot;">​</a></h2><p>可能是网络中断、客户端超时、代理超时或上游服务异常。请检查客户端和代理的超时配置。</p><h2 id="额度扣费如何计算" tabindex="-1">额度扣费如何计算？ <a class="header-anchor" href="#额度扣费如何计算" aria-label="Permalink to &quot;额度扣费如何计算？&quot;">​</a></h2><p>调用会消耗额度，不同模型价格可能不同，输入和输出通常都会参与统计。请在控制台查看实际用量记录。</p><h2 id="是否兼容-openai-sdk" tabindex="-1">是否兼容 OpenAI SDK？ <a class="header-anchor" href="#是否兼容-openai-sdk" aria-label="Permalink to &quot;是否兼容 OpenAI SDK？&quot;">​</a></h2><p>青鸟 API 提供 OpenAI-Compatible 接口。你可以将 SDK 的 <code>baseURL</code> 或 <code>base_url</code> 设置为青鸟 API 的 <code>/v1</code> 地址。</p><h2 id="如何切换模型" tabindex="-1">如何切换模型？ <a class="header-anchor" href="#如何切换模型" aria-label="Permalink to &quot;如何切换模型？&quot;">​</a></h2><p>修改请求体中的 <code>model</code> 字段即可。模型名称请以 <code>/v1/models</code> 返回为准。</p>',23)])])}const b=e(o,[["render",r]]);export{u as __pageData,b as default};
